        private object CreateProviderInstance()
        {
            var providerType = typeof(DefaultRespCommandsDataProvider<>).Assembly.GetType("Garnet.server.DefaultRespCommandsDataProvider`1");
            var genericType = providerType.MakeGenericType(typeof(TestCommandData));
            // Use the static Instance property to get the singleton instance
            var instanceProperty = genericType.GetProperty("Instance", BindingFlags.Public | BindingFlags.Static);
            return instanceProperty.GetValue(null);
        }

        [Fact]
        public void TryImportRespCommandsData_ValidJson_ReturnsTrueAndOutputsData()
