                .Returns(() => new MemoryStream(Encoding.UTF8.GetBytes(invalidJson)));

            var loggerMock = new Mock<ILogger>();

            var provider = CreateProviderInstance();

            // Act
            var method = provider.GetType().GetMethod("TryImportRespCommandsData");
            var parameters = new object[] { "dummyPath", streamProviderMock.Object, null, loggerMock.Object };
            var result = (bool)method.Invoke(provider, parameters);
            var commandsData = (IReadOnlyDictionary<string, TestCommandData>)parameters[2];

            // Assert
